static String classifyPort(int port) {
    if (port <= 1023) return "WELL-KNOWN";
    if (port <= 49151) return "REGISTERED";
    return "DYNAMIC";
}
System.out.println(classifyPort(22)+" "+classifyPort(8080)+" "+classifyPort(50000));

String[][] fakty = {
    {"Polaczeniowosc", "TCP: tak (handshake), UDP: nie"},
