};
for (String[] f : fakty) System.out.println(f[0]+": "+f[1]);

static boolean isValidIPv4(String s) {
    String[] czesci = s.split("\\.");
    if (czesci.length != 4) return false;
    for (String c : czesci) {
        try { int n = Integer.parseInt(c); if (n < 0 || n > 255) return false; } catch (NumberFormatException e) { return false; }
    }
    return true;
}
System.out.println(isValidIPv4("192.168.0.1")+" "+isValidIPv4("999.1.1.1"));

static boolean isPrivateIp(String ip) {
    String[] cz = ip.split("\\.");
    int pierwszy = Integer.parseInt(cz[0]), drugi = Integer.parseInt(cz[1]);
    if (pierwszy == 10) return true;
    if (pierwszy == 172 && drugi >= 16 && drugi <= 31) return true;
    if (pierwszy == 192 && drugi == 168) return true;
    return false;
}
for (String ip : new String[]{"10.0.0.5","172.20.1.1","192.168.1.1","8.8.8.8"}) System.out.println(ip+": "+isPrivateIp(ip));

