static int defaultPortForScheme(String scheme) {
    return switch (scheme) {
        case "http" -> 80;
        case "https" -> 443;
        case "ftp" -> 21;
        case "ssh" -> 22;
        default -> -1;
    };
}
for (String s : new String[]{"http","https","ftp","ssh"}) System.out.println(s+": "+defaultPortForScheme(s));

static String recommendProtocol(String scenario) {
    String s = scenario.toLowerCase();
    if (s.contains("wideo") || s.contains("gra")) return "UDP";
    if (s.contains("plik") || s.contains("transakcja")) return "TCP";
    return "TCP";
}
for (String sc : new String[]{"transmisja wideo na zywo","gra online","transfer pliku","transakcja bankowa"}) System.out.println(sc+": "+recommendProtocol(sc));

int[] porty = {22,80,443,1024,8080,49152,65000};
Map<String,Integer> licznik = new HashMap<>();
for (int p : porty) licznik.merge(classifyPort(p), 1, Integer::sum);
System.out.println(licznik);

