static String classifyIp(String ip) {
    if (ip.equals("127.0.0.1")) return "LOOPBACK";
    if (isPrivateIp(ip)) return "PRYWATNY";
    return "PUBLICZNY";
}
for (String ip : new String[]{"127.0.0.1","192.168.1.1","8.8.8.8","10.0.0.1"}) System.out.println(ip+": "+classifyIp(ip));

