slownik.forEach((k,v) -> System.out.println(k+" - "+v));

class EndpointBuilder {
    static InetSocketAddress build(String host, String scheme, int port) {
        int finalPort = port == 0 ? defaultPortForScheme(scheme) : port;
        return new InetSocketAddress(host, finalPort);
    }
}
System.out.println(EndpointBuilder.build("example.com", "https", 0));
System.out.println(EndpointBuilder.build("example.com", "http", 8080));

static String decideProtocol(boolean latency, boolean reliability) {
    if (reliability) return "TCP";
    return latency ? "UDP" : "TCP";
}
for (boolean l : new boolean[]{true,false}) for (boolean r : new boolean[]{true,false}) System.out.println("latency="+l+" reliability="+r+" -> "+decideProtocol(l,r));

String[] adresy = {"192.168.1.1","10.0.0.1","192.168.50.5","8.8.8.8","192.168.0.1"};
List<String> pasujace = new ArrayList<>();
for (String ip : adresy) { String[] cz = ip.split("\\."); if (cz[0].equals("192") && cz[1].equals("168")) pasujace.add(ip); }
System.out.println("liczba: "+pasujace.size()+" lista: "+pasujace);

Map<String,String> tabelaRoutingu = new LinkedHashMap<>();
tabelaRoutingu.put("192.168.1.", "brama-podsieci-1");
tabelaRoutingu.put("192.168.", "brama-domowa");
tabelaRoutingu.put("10.", "brama-firmowa");
static String findRoute(Map<String,String> tabela, String ip) {
    String najlepszyPrefiks = ""; String wynik = "BRAK TRASY";
    for (Map.Entry<String,String> e : tabela.entrySet()) if (ip.startsWith(e.getKey()) && e.getKey().length() > najlepszyPrefiks.length()) { najlepszyPrefiks = e.getKey(); wynik = e.getValue(); }
    return wynik;
}
System.out.println(findRoute(tabelaRoutingu, "192.168.1.5"));
System.out.println(findRoute(tabelaRoutingu, "192.168.99.5"));

static void simulateConnectionLifecycle(String clientName) {
    System.out.println(clientName+": SYN ->");
    System.out.println("serwer: <- SYN-ACK");
    System.out.println(clientName+": ACK ->");
    System.out.println(clientName+": DATA: 'zapytanie HTTP' ->");
    System.out.println("serwer: <- DATA: 'odpowiedz HTTP'");
    System.out.println(clientName+": FIN ->");
    System.out.println("serwer: <- ACK");
    System.out.println("serwer: <- FIN");
    System.out.println(clientName+": ACK ->");
}
simulateConnectionLifecycle("Klient-1");

record Scenariusz(String host, int port, String opis) {}
List<Scenariusz> scenariusze = List.of(
    new Scenariusz("web.example.com", 80, "strona WWW"),
    new Scenariusz("game.example.com", 27015, "gra online"),
    new Scenariusz("dns.example.com", 53, "zapytanie DNS")
);
for (Scenariusz s : scenariusze) {
    boolean poprawnyPort = s.port() >= 0 && s.port() <= 65535;
    System.out.println(s.host()+":"+s.port()+" ("+s.opis()+") -> "+classifyPort(s.port())+", protokol: "+recommendProtocol(s.opis())+", port poprawny: "+poprawnyPort);
}

